REPLACE INTO `faction_dbc` (`ID`,`ReputationIndex`,`ReputationRaceMask_1`,`ReputationRaceMask_2`,`ReputationRaceMask_3`,`ReputationRaceMask_4`,`ReputationClassMask_1`,`ReputationClassMask_2`,`ReputationClassMask_3`,`ReputationClassMask_4`,`ReputationBase_1`,`ReputationBase_2`,`ReputationBase_3`,`ReputationBase_4`,`ReputationFlags_1`,`ReputationFlags_2`,`ReputationFlags_3`,`ReputationFlags_4`,`ParentFactionID`,`ParentFactionMod_1`,`ParentFactionMod_2`,`ParentFactionCap_1`,`ParentFactionCap_2`,`Name_Lang_enUS`,`Name_Lang_enGB`,`Name_Lang_koKR`,`Name_Lang_frFR`,`Name_Lang_deDE`,`Name_Lang_enCN`,`Name_Lang_zhCN`,`Name_Lang_enTW`,`Name_Lang_zhTW`,`Name_Lang_esES`,`Name_Lang_esMX`,`Name_Lang_ruRU`,`Name_Lang_ptPT`,`Name_Lang_ptBR`,`Name_Lang_itIT`,`Name_Lang_Unk`,`Name_Lang_Mask`,`Description_Lang_enUS`,`Description_Lang_enGB`,`Description_Lang_koKR`,`Description_Lang_frFR`,`Description_Lang_deDE`,`Description_Lang_enCN`,`Description_Lang_zhCN`,`Description_Lang_enTW`,`Description_Lang_zhTW`,`Description_Lang_esES`,`Description_Lang_esMX`,`Description_Lang_ruRU`,`Description_Lang_ptPT`,`Description_Lang_ptBR`,`Description_Lang_itIT`,`Description_Lang_Unk`,`Description_Lang_Mask`) VALUES (970,65,16383,0,0,0,0,0,0,0,-2500,0,0,0,0,0,0,0,980,0,0,5,5,'Sporeggar','','스포어가르','Sporeggar','Sporeggar','','孢子村','','','Esporaggar','Esporaggar','Спореггар','','','','',16712190,'The sporelings are a mostly peaceful race of mushroom-men native to Outland. Their home is located in the southern bogs of Zangarmarsh. ','','스포어가르는 아웃랜드 토착 종족인 평화로운 버섯인간이 살고 있는 마을입니다. 이 마을은 장가르 습지대의 남부 늪지대에 위치하고 있습니다.','Les sporelins sont un peuple d’hommes-champignons paisibles, originaires de l’Outreterre. Ils vivent dans les tourbières méridionales du marécage de Zangar.','Die Sporlinge sind ein vornehm','','生活在外域的孢子人是一个非常温和的种族。他们的家园就坐落在赞','','','Los esporinos son una raza en su mayoría pacífica de hombres champiñón nativos de Terrallende. Su hogar se encuentra en las ciénagas del sur de la Marisma de Zangar.','Los esporinos son una raza en su mayoría pacífica de hombres champiñón nativos de Terrallende. Su hogar se encuentra en las ciénagas del sur de la Marisma de Zangar.','Спорлинги – мирная раса, издавна населяющая Запределье. Их дом находится в южной части Зангартопи.','','','','',16712190);
REPLACE INTO `faction_dbc` (`ID`,`ReputationIndex`,`ReputationRaceMask_1`,`ReputationRaceMask_2`,`ReputationRaceMask_3`,`ReputationRaceMask_4`,`ReputationClassMask_1`,`ReputationClassMask_2`,`ReputationClassMask_3`,`ReputationClassMask_4`,`ReputationBase_1`,`ReputationBase_2`,`ReputationBase_3`,`ReputationBase_4`,`ReputationFlags_1`,`ReputationFlags_2`,`ReputationFlags_3`,`ReputationFlags_4`,`ParentFactionID`,`ParentFactionMod_1`,`ParentFactionMod_2`,`ParentFactionCap_1`,`ParentFactionCap_2`,`Name_Lang_enUS`,`Name_Lang_enGB`,`Name_Lang_koKR`,`Name_Lang_frFR`,`Name_Lang_deDE`,`Name_Lang_enCN`,`Name_Lang_zhCN`,`Name_Lang_enTW`,`Name_Lang_zhTW`,`Name_Lang_esES`,`Name_Lang_esMX`,`Name_Lang_ruRU`,`Name_Lang_ptPT`,`Name_Lang_ptBR`,`Name_Lang_itIT`,`Name_Lang_Unk`,`Name_Lang_Mask`,`Description_Lang_enUS`,`Description_Lang_enGB`,`Description_Lang_koKR`,`Description_Lang_frFR`,`Description_Lang_deDE`,`Description_Lang_enCN`,`Description_Lang_zhCN`,`Description_Lang_enTW`,`Description_Lang_zhTW`,`Description_Lang_esES`,`Description_Lang_esMX`,`Description_Lang_ruRU`,`Description_Lang_ptPT`,`Description_Lang_ptBR`,`Description_Lang_itIT`,`Description_Lang_Unk`,`Description_Lang_Mask`) VALUES (978,66,7245,9138,0,0,0,0,0,0,-1200,-42000,0,0,16,0,0,0,980,0,0,5,5,'Kurenai','','쿠레나이','Kurenaï','Kurenai','','库雷尼','','','Kurenai','Kurenai','Куренай','','','','',16712190,'Draenei for ""redeemed.""  These Broken have escaped the grasp of their various slavers in Outland and have made their home in Nagrand.  It is there that they seek to rediscover their destiny.','','이들은 타락에서 다시 회복된 드레나이들입니다. 이 뒤틀린 드레나이들은 아웃랜드의 지배 계급으로부터 탈출하여 나그란드에 정착하였습니다. 거기서 이들은 자신들의 운명을 되찾으려는 노력을 기울이고 있습니다.','Ce mot signifie « rachetés » en draeneï. Après avoir échappé au joug des esclavagistes de l''Outreterre, ces Roués se sont installés en Nagrand. C''est là qu''ils cherchent à redécouvrir leur destinée.','Draeneiisch für ""erlöst"". Di','','在德莱尼语中意为“得到救赎”。这些从各种奴役和控制中逃出来的','','','En draenei significa ""redimidos."" Estos Tábidos han escapado de la esclavitud en Terrallende y han hecho de Nagrand su hogar. Ahí esperan redescubrir su destino.','En draenei significa ""redimidos."" Estos Tábidos han escapado de la esclavitud en Terrallende y han hecho de Nagrand su hogar. Ahí esperan redescubrir su destino.','Дреней – значит ""Искупленный"". Эти Падшие, сумевшие вырваться из рабства и избравшие своим домом Награнд, стремятся вновь обрести свою судьбу.','','','','',16712190);
